#:property PublishAot=false

// Find the earliest Friday the 13th from 0001-01-01 (proleptic Gregorian)
// and count total Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th
DateOnly date = new(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
{
    date = date.AddMonths(1);
}
Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// Count Friday the 13ths in one 400-year cycle (0001-01-01 to 0400-12-31)
// The Gregorian calendar repeats every 400 years.
int count = 0;
var first = new DateOnly(1, 1, 13);
var limit = new DateOnly(401, 1, 13);
DateOnly d = first;
while (d < limit)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: distribution by month
var byMonth = new int[12];
d = first;
while (d < limit)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        byMonth[d.Month - 1]++;
    d = d.AddMonths(1);
}
Console.WriteLine("\nDistribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-10} {byMonth[m]}");

